package com.regional.corebanking.payment.infrastructure.amplitude;
import org.junit.jupiter.api.Test; import java.sql.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class PaymentExecutionSqlDialectTest {
 @Test void preservesEvidence(){var d=new InformixPaymentExecutionSqlDialect();assertThat(d.findCustomerOpposition()).contains("bkoppcli");assertThat(d.findAvailableFunds()).contains("a.sin-nvl(a.minds,0)+nvl(maut,0) as solde");assertThat(d.findAccountingDatePrimary()).contains("mnt2");assertThat(d.findNightMode()).contains("SITE-CENT");assertThat(d.findMaxEventNumber("BKEVE")).isEqualTo("SELECT MAX(eve) AS eve FROM BKEVE WHERE ope = ?");assertThat(d.countEventNumber("BKEVE_EOD")).isEqualTo("SELECT COUNT(*) AS nbr FROM BKEVE_EOD WHERE eve = ? AND ope = ?");assertThat(d.findHolidays()).isEqualTo("select jourfer from bkfer where TO_CHAR(jourfer,'%Y')=? ");}
 @Test void rejectsUnknownEventTable(){var d=new InformixPaymentExecutionSqlDialect();assertThatThrownBy(()->d.findMaxEventNumber("OTHER")).isInstanceOf(IllegalArgumentException.class);}
 @Test void onlyInformixDirtyRead()throws Exception{Connection c=mock(Connection.class);Statement s=mock(Statement.class);when(c.createStatement()).thenReturn(s);new InformixPaymentExecutionSqlDialect().prepareConnection(c);verify(s).execute("SET ISOLATION TO DIRTY READ");clearInvocations(c,s);new OraclePaymentExecutionSqlDialect().prepareConnection(c);verifyNoInteractions(s);}
}
